const topic = $json.topic;

const styles = [
  { name: "3D Render", description: "Clean 3D render with soft shadows, studio lighting, smooth materials, subtle reflections" },
  { name: "Neon Cyberpunk", description: "Dark cyberpunk aesthetic with neon glow, holographic accents, deep shadows, electric colors" },
  { name: "Flat Design", description: "Modern flat design illustration, bold vibrant colors, clean geometric shapes, no gradients" },
  { name: "Isometric", description: "Isometric 3D illustration, clean lines, pastel palette, minimal shadows, technical diagram style" },
  { name: "Realistic Photo", description: "Cinematic photograph, bokeh background, professional studio lighting, ultra detailed, 8k" },
  { name: "Line Art", description: "Minimalist technical line art, single weight strokes, lots of white space, clean and elegant" },
  { name: "Glassmorphism", description: "Glassmorphic UI style, frosted glass panels, gradient backgrounds, blurred translucent layers" },
  { name: "Retro Synthwave", description: "Retro 80s synthwave aesthetic, grid landscapes, neon pinks and purples, VHS glow effects" }
];

// Avoid repeating the same style twice in a row
const staticData = $getWorkflowStaticData('global');
const lastStyle = staticData.lastStyle || null;

let available = styles.filter(s => s.name !== lastStyle);
if (available.length === 0) { available = styles; }

const style = available[Math.floor(Math.random() * available.length)];
staticData.lastStyle = style.name;

return [{ json: { topic, styleName: style.name, styleDescription: style.description } }];

// Reuse the Cloudflare account ID if we already fetched it once
const staticData = $getWorkflowStaticData('global');
if (staticData.cfAccountId) {
  return [{ json: { cached: true, accountId: staticData.cfAccountId } }];
}
return [{ json: { cached: false } }];

const staticData = $getWorkflowStaticData('global');
const accountId = $json.result[0].id;
staticData.cfAccountId = accountId;
return [{ json: { accountId } }];

