let post = $('Post Maker').first().json.output || '';
const MAX_LENGTH = 2900;

// Strip markdown that LinkedIn won't render
post = post
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .replace(/\*(.*?)\*/g, '$1')
  .replace(/^#{1,6}\s/gm, '')
  .replace(/`{1,3}/g, '')
  .trim();

// Enforce a maximum of 3 hashtags (drop extras from the end)
const hashtags = post.match(/#[A-Za-z0-9_]+/g) || [];
if (hashtags.length > 3) {
  let count = 0;
  post = post
    .replace(/#[A-Za-z0-9_]+/g, m => (++count <= 3 ? m : ''))
    .replace(/[ \t]+\n/g, '\n')
    .trim();
}

// Trim to max length on a word boundary
if (post.length > MAX_LENGTH) {
  post = post.substring(0, MAX_LENGTH);
  const lastSpace = post.lastIndexOf(' ');
  if (lastSpace > 0) post = post.substring(0, lastSpace);
  post += '...';
}

// Quality gate: never publish empty or suspiciously short content
if (!post || post.length < 50) {
  throw new Error('Generated post is too short or empty - aborting to avoid publishing bad content.');
}

return [{ json: { output: post } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.postLog) { staticData.postLog = []; }

const topic = $('Topic Randomiser').first().json.topic;
const postContent = $('Post Trimmer').first().json.output;
const imageStyle = $('Style Randomiser').first().json.styleName;
const now = new Date().toISOString();

let success = true;
let postType = 'image';
let errorMsg = null;

try {
  const result = $('Create a post').first().json;
  if (result && result.error) { success = false; errorMsg = String(result.error); }
} catch (e) {
  try {
    const result = $('Create text-only post').first().json;
    postType = 'text-only';
    if (result && result.error) { success = false; errorMsg = String(result.error); }
  } catch (e2) {
    success = false;
    postType = 'unknown';
    errorMsg = 'No post node executed';
  }
}

staticData.postLog.push({
  date: now,
  topic: topic,
  postLength: postContent.length,
  imageStyle: imageStyle,
  postType: postType,
  status: success ? 'posted' : 'failed',
  error: errorMsg
});

if (staticData.postLog.length > 50) {
  staticData.postLog = staticData.postLog.slice(-50);
}

return [{ json: { logged: true, topic, date: now, postType, status: success ? 'posted' : 'failed', error: errorMsg } }];
